            aOrbiterH = ((aOrbiterH + aOrbiterD) + 0x0B895259572891DCULL) + aOUSaltB[((aIndex + 201U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterH) ^ 0xBA1BBBFA6F7ECD5AULL) ^ aOUSaltE[(((511U - aIndex) + 274U)) & S_SALT1];
