            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0x8FDD0862BD638A79ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0x666CF3C3E25EE0D8ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x2E9E5477EF53AAADULL), 37U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterF) + 0x736BFBB65B638493ULL) + aOUSaltC[((aIndex + 345U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x561F2DF67E07352BULL;
