            aOrbiterB = (aOrbiterB ^ aOrbiterJ) ^ 0xE25BF1FB9A52B4E7ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xA684FACF744669D1ULL), 43U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterI) + 0x469C119DE24E9679ULL) + aOUSaltC[((aIndex + 173U)) & S_SALT1];
