            aWandererF = aWandererF + ((RotL64(aScatter, 37U) + RotL64(aOrbiterK, 3U)) + aOrbiterE);
            aWandererH = aWandererH ^ ((RotL64(aCross, 42U) + RotL64(aOrbiterH, 43U)) + aOrbiterE);
