            aOrbiterD = ((aWandererE + RotL64(aScatter, 39U)) + RotL64(aCarry, 39U)) + 0x75BA93916FD6547CULL;
            aOrbiterJ = (aWandererD + RotL64(aIngress, 43U)) + 0xD99E6C94EB4588A9ULL;
