            aOrbiterK = (aOrbiterK + aOrbiterB) + 0xC0F2D983FA6AE3D6ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0xD63DA7794CFBEDEEULL;
            aOrbiterF = RotL64((aOrbiterF * 0xBB946C57E567BAD1ULL), 57U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0xBA5D0F31196D0AFDULL) + aOUSaltH[(((511U - aIndex) + 434U)) & S_SALT1];
