            aOrbiterG = ((aWandererA + RotL64(aIngress, 60U)) + 0xE24126488BE20B6DULL) + aOASaltF[(((511U - aIndex) + 123U)) & S_SALT1];
            aOrbiterK = (((aWandererC + RotL64(aCross, 47U)) + RotL64(aCarry, 41U)) + 0x03A33CB5EF61C069ULL) + aOASaltB[((aIndex + 193U)) & S_SALT1];
            aOrbiterD = (((aWandererK + RotL64(aScatter, 41U)) + RotL64(aCarry, 57U)) + 0x73FAB83E72C7B769ULL) + aOASaltD[(((511U - aIndex) + 308U)) & S_SALT1];
