            aOrbiterF = RotL64((aOrbiterF * 0x9AF9B11866E4946BULL), 3U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterD) + 0x5388C19F37A1BDD5ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterI) ^ 0x1284316D3D0DB057ULL) ^ aOUSaltB[(((511U - aIndex) + 313U)) & S_SALT1];
