            //
            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0xDDD20740FADA2444ULL) + aOUSaltF[((aIndex + 450U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0xB594CE0C2EAC4360ULL;
