            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x85B0DEDDFBB43ED0ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x35B5CC9DF8C70BD7ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x9618CF1420C5AD4BULL), 29U);
            //
            aIngress = RotL64(aOrbiterD, 5U) ^ aOrbiterK;
            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterI, 11U));
            aIngress = aIngress + (RotL64(aOrbiterB, 37U) ^ aOrbiterE);
            aIngress = aIngress + RotL64(aOrbiterF, 53U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 47U) + RotL64(aOrbiterG, 11U)) + aOrbiterD);
