            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 5U) + RotL64(aCross, 56U)) ^ (RotL64(aPrevious, 19U) ^ RotL64(aCarry, 37U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterG = (aWandererF + RotL64(aScatter, 27U)) + 0xE8F6694EE143C22BULL;
            aOrbiterC = (((aWandererD + RotL64(aIngress, 51U)) + RotL64(aCarry, 11U)) + 0x43EC83D946DFB03DULL) + aOASaltH[(((511U - aIndex) + 199U)) & S_SALT1];
            aOrbiterE = ((aWandererB + RotL64(aPrevious, 19U)) + 0xBAD8B4B841D405EBULL) + aOASaltC[((aIndex + 287U)) & S_SALT1];
            aOrbiterH = (((aWandererA + RotL64(aCross, 58U)) + RotL64(aCarry, 23U)) + 0xE49EAACC7E3B57BBULL) + aOASaltF[((aIndex + 252U)) & S_SALT1];
            aOrbiterB = ((aWandererC + RotL64(aPrevious, 35U)) + RotL64(aCarry, 53U)) + 0x3C56EB5DD579A8CDULL;
            aOrbiterI = (aWandererH + RotL64(aScatter, 43U)) + 0x96B7253EA5D1708BULL;
            aOrbiterF = ((aWandererG + RotL64(aCross, 13U)) + 0xCE1A584F02F093ECULL) + aOASaltG[(((511U - aIndex) + 82U)) & S_SALT1];
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x4E5F8666E2746992ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterG) ^ 0xF5D98968772B62F4ULL) ^ aOUSaltD[((aIndex + 236U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x6F811786574F63E3ULL), 21U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0xCE05033257CAC114ULL) + aOUSaltA[(((511U - aIndex) + 465U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x3C81C55265356C1CULL;
            aOrbiterC = RotL64((aOrbiterC * 0x3235ADEBDF0E3039ULL), 43U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0xC9F8BEC2BDEC163EULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterI) ^ 0x99FDE02A40DF8838ULL) ^ aOUSaltC[((aIndex + 285U)) & S_SALT1];
