            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0x6A67747357E80BA5ULL) + aOUSaltF[(((511U - aIndex) + 322U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterE) ^ 0x95EEF3CC2884BC71ULL) ^ aOUSaltB[(((511U - aIndex) + 197U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x3D0713C6512AE283ULL), 37U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x40D180A6CB12D588ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0xD4D429EA160309A7ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x5921125C5FCA9CF7ULL), 53U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x5A07388FD5DA8A03ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterF) ^ 0x8455C67B510AC88DULL) ^ aOUSaltE[(((511U - aIndex) + 149U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x6D9DCBB2FDA179A1ULL), 13U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0xFC6A84DCCECA6931ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0xC21504AE1909B078ULL;
