            aWandererB = aWandererB + ((((RotL64(aPrevious, 39U) + aOrbiterI) + RotL64(aOrbiterC, 3U)) + RotL64(aCarry, 19U)) + aWUSaltE[(((511U - aIndex) + 239U)) & S_SALT1]);
