            aWandererD = aWandererD ^ (((RotL64(aPrevious, 47U) + aOrbiterE) + RotL64(aOrbiterI, 11U)) + aWUSaltC[((aIndex + 430U)) & S_SALT1]);
            aWandererF = aWandererF + ((((RotL64(aCross, 27U) + RotL64(aOrbiterI, 35U)) + aOrbiterK) + RotL64(aCarry, 13U)) + aWUSaltB[((aIndex + 213U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 35U) + aOrbiterC) + RotL64(aOrbiterJ, 50U));
