            aOrbiterA = (((aWandererI + RotL64(aIngress, 3U)) + RotL64(aCarry, 57U)) + 0xFEE4BDC86C18CA74ULL) + aOASaltA[((aIndex + 467U)) & S_SALT1];
            aOrbiterJ = (aWandererG + RotL64(aPrevious, 13U)) + 0xA5DF719699B07B13ULL;
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0x77E1BE2446B2C6AFULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x8466D32EC2085104ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xCF68ACCF23A6E3CFULL), 57U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0xDEB31D2799246CCDULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x9B1F098E69C235E1ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x0D07D488EEB415D7ULL), 51U);
