            aWandererF = aWandererF ^ ((RotL64(aScatter, 3U) + RotL64(aOrbiterB, 37U)) + aOrbiterI);
            aWandererJ = aWandererJ + (((RotL64(aCross, 39U) + aOrbiterF) + RotL64(aOrbiterH, 5U)) + RotL64(aCarry, 11U));
            aWandererE = aWandererE ^ ((RotL64(aPrevious, 18U) + aOrbiterB) + RotL64(aOrbiterC, 39U));
