            aOrbiterD = RotL64((aOrbiterD * 0xEAE0D5A7B7CBB013ULL), 29U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0x9F3CD21A17B41D3FULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x41A844BD27B046ABULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xF5798DCC426055D3ULL), 43U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0x99B5AB56E49CA499ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0x7DAF7227B8C40637ULL;
