            //
            aOrbiterJ = ((aWandererB + RotL64(aIngress, 51U)) + 0x5B53685E11EE7CA3ULL) + aOASaltH[((aIndex + 189U)) & S_SALT1];
            aOrbiterB = ((aWandererI + RotL64(aScatter, 6U)) + RotL64(aCarry, 13U)) + 0x28F2166C6AEF2307ULL;
            aOrbiterG = (aWandererC + RotL64(aPrevious, 57U)) + 0x2BB7B28331F4DF51ULL;
            aOrbiterE = ((aWandererK + RotL64(aCross, 35U)) + RotL64(aCarry, 29U)) + 0x36CCD29A358BE0F7ULL;
            aOrbiterI = (aWandererF + RotL64(aIngress, 13U)) + 0x86BABCA91F9536DAULL;
            aOrbiterH = (((aWandererG + RotL64(aPrevious, 19U)) + RotL64(aCarry, 57U)) + 0x69DCE2309B1F5161ULL) + aOASaltD[(((511U - aIndex) + 422U)) & S_SALT1];
            aOrbiterA = ((aWandererJ + RotL64(aScatter, 27U)) + 0xDCC5F2CADDACBDEFULL) + aOASaltF[((aIndex + 507U)) & S_SALT1];
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0xD3ED5D05A72BE615ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0xA0E7107A408391A7ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x4561AB3253E6ADA5ULL), 51U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0x8B45F8E940D20A5CULL) + aOUSaltB[(((511U - aIndex) + 210U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterE) ^ 0x2FA6119DEE09879AULL) ^ aOUSaltA[((aIndex + 286U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x0CE229EC9ABAC075ULL), 13U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0xC0FAB548DBA24528ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0xAF2E614555E112C9ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x124D85B9E11EFA05ULL), 21U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterJ) + 0xF83C2BCC097B02F0ULL) + aOUSaltC[(((511U - aIndex) + 278U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0x8F32F3892246A28CULL;
            aOrbiterB = RotL64((aOrbiterB * 0x30D22F5689B9C96DULL), 57U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0xCC4BF6DBC21D8BC2ULL;
