            aOrbiterA = RotL64((aOrbiterA * 0xEB6B0B3DDEC8693BULL), 5U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x588251AE695057A6ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0x7D14D2FA28741EE6ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xFA4D73C8AE2F67C1ULL), 27U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x9049EC249FA8DA51ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0x2E6326044245B6B2ULL) ^ aOUSaltG[((aIndex + 157U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xE39F5018F19B614FULL), 39U);
            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterB, 41U);
