            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererC = aWandererC + ((((RotL64(aPrevious, 41U) + aOrbiterB) + RotL64(aOrbiterA, 3U)) + RotL64(aCarry, 39U)) + aWUSaltE[((aIndex + 47U)) & S_SALT1]);
