            aIngress ^= (RotL64(aPlasmaLaneC[((aIndex + 26939U)) & S_BLOCK1], 19U) ^ RotL64(aKineticLaneB[((S_BLOCK1 - aIndex + 28492U)) & S_BLOCK1], 51U));
