            aCross = (RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 29245U)) & S_BLOCK1], 11U) ^ RotL64(aCrystalLaneB[((S_BLOCK1 - aIndex + 29435U)) & S_BLOCK1], 35U));
            aCross ^= RotL64(aPlasmaLaneA[((aIndex + 25140U)) & S_BLOCK1], 54U);
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateBDomainWordCross));
            //
            aScatter = (RotL64(aCarry, 5U) + RotL64(aPrevious, 19U)) + (RotL64(aIngress, 52U) ^ RotL64(aCross, 35U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterA = ((aWandererH + RotL64(aIngress, 57U)) + RotL64(aCarry, 5U)) + 0x448E7587480C725CULL;
            aOrbiterJ = (aWandererE + RotL64(aPrevious, 29U)) + 0x52D9EA8662B08FC3ULL;
            aOrbiterG = (((aWandererC + RotL64(aCross, 43U)) + RotL64(aCarry, 57U)) + 0xA08CEF5274F8F51CULL) + aOASaltB[((aIndex + 354U)) & S_SALT1];
            aOrbiterI = ((aWandererB + RotL64(aScatter, 13U)) + 0x2A24273425944A62ULL) + aOASaltG[(((511U - aIndex) + 183U)) & S_SALT1];
            aOrbiterH = ((aWandererJ + RotL64(aIngress, 37U)) + 0xCED2E755F7F4BB93ULL) + aOASaltA[((aIndex + 493U)) & S_SALT1];
            aOrbiterB = (((aWandererI + RotL64(aPrevious, 20U)) + RotL64(aCarry, 43U)) + 0x04C11CD3272FDA2FULL) + aOASaltE[(((511U - aIndex) + 187U)) & S_SALT1];
            aOrbiterE = (aWandererF + RotL64(aCross, 3U)) + 0xB6589974145C8A9CULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterJ) + 0x6EA11988E82E75D3ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterA) ^ 0x8C0E5E1A8EB208A0ULL) ^ aOUSaltE[((aIndex + 102U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xC906352E2CDEEC41ULL), 5U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0xD6F5F711D9E1DF98ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterG) ^ 0x67913C7479952628ULL) ^ aOUSaltB[(((511U - aIndex) + 75U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x7BB5ADBE438508C3ULL), 19U);
