            aOrbiterB = (aOrbiterB + aOrbiterA) + 0xD09B21013B26D1F6ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x776821E8E66DE0B8ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x534372EFD2395967ULL), 51U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterH) + 0xD903C449067DE167ULL) + aOUSaltH[((aIndex + 125U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterI) ^ 0xD3D1D238DD0873DBULL) ^ aOUSaltC[(((511U - aIndex) + 223U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x5D712C91AD4F3D9FULL), 37U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0x94AD5BE5247B3559ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x1B1F23542DD876BFULL;
            aOrbiterA = RotL64((aOrbiterA * 0x33A7C704344CAB19ULL), 13U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0xFB5BD79A58DD3484ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0x6968C3BFBC43415FULL;
            aOrbiterB = RotL64((aOrbiterB * 0x140690FB94DE7A8BULL), 57U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterG) + 0x9D7E0AE85ED96830ULL) + aOUSaltD[((aIndex + 163U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x3CDD948338957CF6ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x52A6CC92735363CBULL), 27U);
            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterB, 57U);
