            aWandererI = aWandererI ^ ((RotL64(aScatter, 3U) + RotL64(aOrbiterE, 57U)) + aOrbiterI);
            aWandererH = aWandererH + ((((RotL64(aPrevious, 29U) + aOrbiterG) + RotL64(aOrbiterH, 3U)) + RotL64(aCarry, 43U)) + aWUSaltA[((aIndex + 280U)) & S_SALT1]);
            aWandererE = aWandererE ^ (((RotL64(aIngress, 23U) + aOrbiterB) + RotL64(aOrbiterE, 29U)) + aWUSaltH[(((511U - aIndex) + 37U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererF ^ RotL64(aWandererE, 39U));
